<script setup lang="ts">
definePageMeta({layout:'admin',middleware:'admin'})
const {data:settings,refresh:refreshSettings}=await useFetch<any>('/api/admin/settings')
const {data:holidays,refresh:refreshHolidays}=await useFetch<any[]>('/api/admin/holidays')
const weekly=ref<Record<string,string[][]>>({}),saveBusy=ref(false),error=ref(''),notice=ref('')
const holidayDate=ref(''),reason=ref('تعطیلی مطب'),showCal=ref(false)
watch(settings,(v)=>{if(v?.working_hours)weekly.value=structuredClone(v.working_hours)},{immediate:true})
const days=[{n:'6',name:'شنبه'},{n:'0',name:'یکشنبه'},{n:'1',name:'دوشنبه'},{n:'2',name:'سه‌شنبه'},{n:'3',name:'چهارشنبه'},{n:'4',name:'پنجشنبه'},{n:'5',name:'جمعه'}]
function addSlot(day:string){if(!weekly.value[day])weekly.value[day]=[];weekly.value[day].push(['09:00','13:00'])}
async function saveHours(){if(!settings.value)return;error.value='';notice.value='';saveBusy.value=true;try{await $fetch('/api/admin/settings',{method:'PUT',body:{...settings.value,working_hours:weekly.value}});await refreshSettings();notice.value='ساعات کاری ذخیره شد.'}catch(e){error.value=humanError(e)}finally{saveBusy.value=false}}
async function addHoliday(){if(!holidayDate.value){error.value='روز تعطیل را از تقویم انتخاب کنید.';return}error.value='';try{await $fetch('/api/admin/holidays',{method:'POST',body:{date:holidayDate.value,reason:reason.value}});await refreshHolidays();holidayDate.value='';notice.value='روز تعطیل ثبت شد.'}catch(e){error.value=humanError(e)}}
async function removeHoliday(id:number){if(!confirm('تعطیلی این روز حذف شود؟'))return;try{await $fetch(`/api/admin/holidays/${id}`,{method:'DELETE'});await refreshHolidays();notice.value='روز تعطیل حذف شد.'}catch(e){error.value=humanError(e)}}
useSeoMeta({title:'ساعات کاری و تعطیلات | مدیریت',robots:'noindex,nofollow'})
</script>
<template><div><div class="mb-8"><span class="eyebrow">تنظیم تقویم رزرو</span><h1 class="text-3xl font-extrabold text-jade-800 mt-2">ساعات کاری و تعطیلات</h1><p class="text-xs text-[#829d8e] mt-2">روزهای تعطیل و زمان‌های خارج از برنامه به بیماران نمایش داده نمی‌شوند.</p></div><p v-if="error" role="alert" class="p-4 bg-red-50 text-red-700 rounded-xl text-xs mb-5">{{error}}</p><p v-if="notice" class="p-4 bg-green-50 text-green-700 rounded-xl text-xs mb-5">{{notice}}</p><div class="grid xl:grid-cols-[1.3fr_1fr] gap-6"><div class="glass-card p-6 sm:p-8"><h2 class="text-lg font-bold text-jade-800 mb-1">برنامه هفتگی</h2><p class="text-[11px] text-[#94a79b] mb-7">برای هر روز می‌توانید چند بازه کاری بدون تداخل ثبت کنید.</p><div v-for="d in days" :key="d.n" class="border-b border-[#edf3ed] py-5"><div class="flex flex-wrap gap-3 items-center justify-between"><span class="font-bold text-[13px] min-w-[80px]">{{d.name}}</span><button class="text-xs text-jade-700 flex gap-1 items-center" @click="addSlot(d.n)"><Icon name="plus" :size="16" /> بازه جدید</button></div><div v-if="!weekly[d.n]?.length" class="text-[11px] text-[#9aaa9f] mt-3">تعطیل</div><div v-for="(range,i) in weekly[d.n]||[]" :key="i" class="mt-3 flex items-center gap-2 flex-wrap"><input v-model="range[0]" type="time" class="input-field !w-[120px] !min-h-[39px]" /><span class="text-xs text-[#90a499]">تا</span><input v-model="range[1]" type="time" class="input-field !w-[120px] !min-h-[39px]" /><button class="p-2 text-rose-600" title="حذف بازه" @click="weekly[d.n].splice(i,1)"><Icon name="x" :size="17" /></button></div></div><button :disabled="saveBusy" class="btn-main mt-7" @click="saveHours"><Icon name="check" :size="18" /> ذخیره برنامه هفتگی</button></div><div class="space-y-6"><div class="glass-card p-6 sm:p-8"><h2 class="font-bold text-jade-800 text-lg mb-2">ثبت روز تعطیل</h2><p class="text-xs leading-7 text-[#94a79b] mb-6">روزهای تعطیل و مرخصی، امکان رزرو ندارند.</p><button class="btn-light w-full justify-between" @click="showCal=!showCal"><Icon name="calendar-days" :size="17" />{{holidayDate?faDate(holidayDate):'انتخاب روز از تقویم شمسی'}}</button><JalaliCalendar v-if="showCal" v-model="holidayDate" :horizon="365" class="mt-3" /><label class="field-label mt-5">عنوان یا دلیل تعطیلی</label><input v-model="reason" class="input-field" maxlength="200" /><button class="btn-main mt-5" @click="addHoliday"><Icon name="plus" :size="17" /> ثبت تعطیلی</button></div><div class="glass-card p-6 sm:p-8"><h2 class="font-bold text-jade-800 mb-5">روزهای تعطیل ثبت‌شده</h2><div v-for="day in holidays||[]" :key="day.id" class="flex gap-4 justify-between items-center py-3 border-b border-[#eaf0ea]"><div><p class="text-xs font-bold">{{faDate(day.date)}}</p><p class="text-[11px] text-[#97a89c] mt-1">{{day.reason}}</p></div><button class="text-rose-600 p-2" aria-label="حذف تعطیلی" @click="removeHoliday(day.id)"><Icon name="trash-2" :size="17" /></button></div><p v-if="!holidays?.length" class="text-xs text-[#94a99e]">روز تعطیلی ثبت نشده است.</p></div></div></div></div></template>
